interface ContentFormProps {
	contentType: SerializedContentType;
	initialData?: Record<string, unknown>;
	initialSlug?: string;
	initialPublishAt?: string | null;
	isEditing?: boolean;
	onSubmit: (data: {
		slug: string;
		data: Record<string, unknown>;
		publishAt?: string | null;
	}) => Promise<void>;
	onCancel?: () => void;
	/**
	 * Server-side field validation errors (`StackError.errors`), applied to
	 * the matching form fields for inline display.
	 */
	fieldErrors?: Record<string, string | string[]>;
	/** Non-field submit error to display above the form */
	errorMessage?: string;
	/** External submit-in-flight state (e.g. from a resource `useForm`) */
	isSubmitting?: boolean;
}

/**
 * Applies server-side field validation errors onto react-hook-form field
 * state, and clears previously applied server errors that are no longer
 * present. The form instance arrives asynchronously (captured from
 * SteppedAutoForm's `onValuesChange`) and is `null` for multi-step forms.
 */
function useServerFieldErrors<T extends FieldValues>(
	form: UseFormReturn<T> | null,
	fieldErrors: Record<string, string | string[]>,
) {
	const appliedFieldsRef = useRef<string[]>([]);

	useEffect(() => {
		if (!form) return;

		// Clear stale server errors from fields that are no longer failing
		for (const field of appliedFieldsRef.current) {
			if (field in fieldErrors) continue;
			const { error } = form.getFieldState(field as FieldPath<T>);
			if (error?.type === "server") {
				form.clearErrors(field as FieldPath<T>);
			}
		}
		appliedFieldsRef.current = Object.keys(fieldErrors);

		for (const [field, message] of Object.entries(fieldErrors)) {
			form.setError(field as FieldPath<T>, {
				type: "server",
				message: Array.isArray(message) ? message.join(", ") : message,
			});
		}
	}, [fieldErrors, form]);
}

/**
 * Build field configuration for AutoForm with CMS-specific file upload handling.
 *
 * Uses the shared buildFieldConfigFromJsonSchema from auto-form/helpers as a base,
 * then adds special handling for "file" fieldType to inject CMSFileUpload component
 * ONLY if no custom component is provided via fieldComponents.
 *
 * @param jsonSchema - The JSON Schema from the content type (with fieldType embedded in properties)
 * @param uploadImage - The uploadImage function from overrides (for file fields)
 * @param fieldComponents - Custom field components from overrides
 */
interface JsonSchemaProperty {
	fieldType?: string;
	relation?: RelationConfig;
	[key: string]: unknown;
}

function buildFieldConfigFromJsonSchema(
	jsonSchema: Record<string, unknown>,
	uploadImage?: (file: File) => Promise<string>,
	fieldComponents?: Record<
		string,
		React.ComponentType<AutoFormInputComponentProps>
	>,
	imagePicker?: React.ComponentType<{ onSelect: (url: string) => void }>,
	imageInputField?: React.ComponentType<{
		value: string;
		onChange: (value: string) => void;
		isRequired?: boolean;
	}>,
): FieldConfig<Record<string, unknown>> {
	// Get base config from shared utility (handles fieldType from JSON Schema,
	// including per-item configs for arrays of objects).
	const baseConfig = buildFieldConfigBase(jsonSchema, fieldComponents);

	const properties = jsonSchema.properties as
		| Record<string, JsonSchemaProperty>
		| undefined;

	if (!properties) return baseConfig;

	// Recursively walk the JSON Schema properties and inject CMS-specific custom
	// components (file upload, relation picker) for any field with a matching
	// fieldType, regardless of nesting depth. Targets:
	//   - top-level fields
	//   - properties of nested object fields
	//   - properties of array items (e.g. `components: z.array(z.object({...}))`)
	//
	// `targetConfig` is the FieldConfigObject slot to mutate for the property at
	// `key`. The recursion mirrors how AutoFormObject + AutoFormArray look up
	// per-property configs: nested object/array per-item configs live as keys
	// alongside their parent's meta on the same FieldConfigObject.
	const injectCustomFieldTypes = (
		props: Record<string, JsonSchemaProperty>,
		targetConfig: Record<string, unknown>,
	) => {
		for (const [key, prop] of Object.entries(props)) {
			// Ensure a slot exists so we can mutate it whether or not the base
			// helper produced an entry for this key.
			const existing =
				(targetConfig[key] as Record<string, unknown> | undefined) ?? {};

			let updated = existing;

			// Handle "file" fieldType when there's NO custom component for "file"
			if (prop.fieldType === "file" && !fieldComponents?.["file"]) {
				if (!uploadImage && !imageInputField) {
					updated = {
						...updated,
						fieldType: () => (
							<div className="rounded-md border border-destructive bg-destructive/10 p-3 text-sm text-destructive">
								File upload requires an <code>uploadImage</code> or{" "}
								<code>imageInputField</code> function in CMS overrides.
							</div>
						),
					};
				} else {
					updated = {
						...updated,
						fieldType: (componentProps: AutoFormInputComponentProps) => (
							<CMSFileUpload
								{...componentProps}
								uploadImage={uploadImage ?? (() => Promise.resolve(""))}
								imageInputField={imageInputField}
								imagePicker={imagePicker}
							/>
						),
					};
				}
			}

			// Handle "relation" fieldType when there's NO custom component for "relation"
			if (
				prop.fieldType === "relation" &&
				prop.relation &&
				!fieldComponents?.["relation"]
			) {
				const relationConfig = prop.relation;
				updated = {
					...updated,
					fieldType: (componentProps: AutoFormInputComponentProps) => (
						<RelationField {...componentProps} relation={relationConfig} />
					),
				};
			}

			// Recurse into nested objects — their per-property configs live as
			// keys on the same parent FieldConfigObject.
			if (prop.properties) {
				injectCustomFieldTypes(
					prop.properties as Record<string, JsonSchemaProperty>,
					updated,
				);
			}

			// Recurse into array items — same convention as nested objects.
			const items = prop.items as JsonSchemaProperty | undefined;
			if (items?.properties) {
				injectCustomFieldTypes(
					items.properties as Record<string, JsonSchemaProperty>,
					updated,
				);
			}

			if (Object.keys(updated).length > 0) {
				targetConfig[key] = updated;
			}
		}
	};

	injectCustomFieldTypes(
		properties,
		baseConfig as unknown as Record<string, unknown>,
	);

	return baseConfig;
}

/**
 * Determine the first string field in the schema for slug auto-generation
 */
function findSlugSourceField(
	jsonSchema: Record<string, unknown>,
): string | null {
	const properties = jsonSchema.properties as Record<string, { type?: string }>;
	if (!properties) return null;

	// Look for common name fields first
	const priorityFields = ["name", "title", "heading", "label"];
	for (const field of priorityFields) {
		if (properties[field]?.type === "string") {
			return field;
		}
	}

	// Fall back to first string field
	for (const [key, value] of Object.entries(properties)) {
		if (value.type === "string") {
			return key;
		}
	}

	return null;
}

export function ContentForm({
	contentType,
	initialData = {},
	initialSlug = "",
	initialPublishAt,
	isEditing = false,
	onSubmit,
	onCancel,
	fieldErrors,
	errorMessage,
	isSubmitting: isSubmittingProp,
}: ContentFormProps) {
	const t = useTranslate();
	const {
		localization,
		uploadImage,
		imagePicker,
		imageInputField,
		fieldComponents,
	} = usePluginOverrides<CMSPluginOverrides>(CMS_PLUGIN_ID);

	const [slug, setSlug] = useState(initialSlug);
	const publishAtEditedRef = useRef(false);
	const aiPublishAtRef = useRef<string | null | undefined>(undefined);
	const [publishAt, setPublishAt] = useState(() => {
		if (!initialPublishAt) return "";
		const date = new Date(initialPublishAt);
		return new Date(date.getTime() - date.getTimezoneOffset() * 60_000)
			.toISOString()
			.slice(0, 16);
	});
	const [slugManuallyEdited, setSlugManuallyEdited] = useState(isEditing);
	const [isSubmittingLocal, setIsSubmittingLocal] = useState(false);
	const [formData, setFormData] =
		useState<Record<string, unknown>>(initialData);
	const [slugError, setSlugError] = useState<string | null>(null);
	const [submitError, setSubmitError] = useState<string | null>(null);

	const isSubmitting = isSubmittingProp || isSubmittingLocal;

	// Single-step forms pass their react-hook-form instance through
	// onValuesChange; multi-step forms pass undefined (no single instance).
	const [formInstance, setFormInstance] = useState<UseFormReturn<
		Record<string, unknown>
	> | null>(null);

	const serverFieldErrors = useMemo(() => fieldErrors ?? {}, [fieldErrors]);
	useServerFieldErrors(formInstance, serverFieldErrors);
	const hasFieldErrors = Object.keys(serverFieldErrors).length > 0;

	// Track if we've already synced prefill data to avoid overwriting user input
	const hasSyncedPrefillRef = useRef(false);

	// Sync formData with initialData when it changes
	// This handles both:
	// 1. Editing mode: always sync when item data is loaded (isEditing=true)
	// 2. Create mode: only sync prefill data ONCE to avoid overwriting user input
	// useState only uses the initial value on mount, so we need this effect for updates
	useEffect(() => {
		const hasData = Object.keys(initialData).length > 0;
		// In edit mode, always sync (user is loading existing data)
		// In create mode, only sync prefill data once
		const shouldSync = hasData && (isEditing || !hasSyncedPrefillRef.current);

		if (shouldSync) {
			setFormData(initialData);
			if (!isEditing) {
				hasSyncedPrefillRef.current = true;
			}
		}
	}, [initialData, isEditing]);

	// Also sync slug when initialSlug changes
	useEffect(() => {
		if (isEditing && initialSlug) {
			setSlug(initialSlug);
		}
	}, [initialSlug, isEditing]);

	// Parse JSON Schema (now includes fieldType embedded in properties)
	const jsonSchema = useMemo(() => {
		try {
			return JSON.parse(contentType.jsonSchema) as Record<string, unknown>;
		} catch {
			return {};
		}
	}, [contentType.jsonSchema]);

	// Convert JSON Schema to Zod schema using formSchemaToZod utility
	// This properly handles date fields (format: "date-time") and min/max date constraints
	const zodSchema = useMemo(() => {
		try {
			return formSchemaToZod(jsonSchema);
		} catch {
			return z.object({});
		}
	}, [jsonSchema]);
	useRegisterPageAIContext({
		routeName: "cms-content-editor",
		pageDescription: JSON.stringify({
			page: "CMS entry draft. Fill only fields in this active content type; the user reviews and saves.",
			contentType: contentType.slug,
			schema: jsonSchema,
			publishAt,
		}).slice(0, 16000),
		clientTools: {
			fillCmsEntryForm: async (input: unknown) => {
				if (isSubmitting)
					return {
						success: false,
						message: "Wait for the entry save to finish.",
					};
				const parsed = z
					.object({
						data: z.record(z.string(), z.unknown()).optional(),
						publishAt: z.iso.datetime({ offset: true }).nullable().optional(),
					})
					.strict()
					.safeParse(input);
				if (!parsed.success)
					return { success: false, message: "Invalid entry draft." };
				const patch = parsed.data.data ?? {};
				const properties = jsonSchema.properties as
					| Record<string, unknown>
					| undefined;
				if (
					Object.keys(patch).some(
						(key) =>
							!properties ||
							!Object.hasOwn(properties, key) ||
							["__proto__", "constructor", "prototype"].includes(key),
					)
				)
					return {
						success: false,
						message: "Draft contains fields outside the active content type.",
					};
				let validation: ReturnType<typeof zodSchema.safeParse>;
				try {
					validation = formSchemaToZod(jsonSchema).safeParse({
						...formData,
						...patch,
					});
				} catch {
					return {
						success: false,
						message: "The active content type could not be validated.",
					};
				}
				if (
					!validation.success &&
					validation.error.issues.some(
						(issue) =>
							issue.path.length === 0 ||
							Object.hasOwn(patch, String(issue.path[0])),
					)
				)
					return {
						success: false,
						message: "Draft values do not match the active content type.",
					};
				for (const [key, value] of Object.entries(patch))
					formInstance?.setValue(key, value, {
						shouldDirty: true,
						shouldValidate: true,
					});
				setFormData((current) => ({ ...current, ...patch }));
				if (parsed.data.publishAt !== undefined) {
					aiPublishAtRef.current = parsed.data.publishAt;
					publishAtEditedRef.current = true;
					const date = parsed.data.publishAt
						? new Date(parsed.data.publishAt)
						: null;
					setPublishAt(
						date
							? new Date(date.getTime() - date.getTimezoneOffset() * 60000)
									.toISOString()
									.slice(0, 16)
							: "",
					);
				}
				return {
					success: true,
					message: "Entry draft updated. Review it before saving.",
				};
			},
		},
	});

	// Build field config for AutoForm (fieldType is now embedded in jsonSchema)
	const fieldConfig = useMemo(
		() =>
			buildFieldConfigFromJsonSchema(
				jsonSchema,
				uploadImage,
				fieldComponents,
				imagePicker,
				imageInputField,
			),
		[jsonSchema, uploadImage, fieldComponents, imagePicker, imageInputField],
	);

	// Find the field to use for slug auto-generation
	const slugSourceField = useMemo(
		() => findSlugSourceField(jsonSchema),
		[jsonSchema],
	);

	// Handle form value changes for slug auto-generation
	const handleValuesChange = (
		values: Record<string, unknown>,
		form?: UseFormReturn<Record<string, unknown>>,
	) => {
		if (form) {
			setFormInstance((current) => (current === form ? current : form));
		}
		setFormData(values);

		// Auto-generate slug from source field if not manually edited
		if (!isEditing && !slugManuallyEdited && slugSourceField) {
			const sourceValue = values[slugSourceField];
			if (typeof sourceValue === "string" && sourceValue.trim()) {
				setSlug(slugify(sourceValue));
			}
		}
	};

	// Handle form submission
	const handleSubmit = async (data: Record<string, unknown>) => {
		setSlugError(null);
		setSubmitError(null);

		if (!slug.trim()) {
			setSlugError(
				localization?.CMS_EDITOR_SLUG_REQUIRED ??
					t("cms.editor.slugRequired", "Slug is required"),
			);
			return;
		}

		setIsSubmittingLocal(true);
		try {
			await onSubmit({
				slug,
				data,
				publishAt:
					aiPublishAtRef.current !== undefined
						? aiPublishAtRef.current
						: publishAtEditedRef.current
							? publishAt
								? new Date(publishAt).toISOString()
								: null
							: (initialPublishAt ?? null),
			});
		} catch (error) {
			const message =
				error instanceof Error
					? error.message
					: (localization?.CMS_TOAST_ERROR ??
						t("cms.toasts.error", "An error occurred. Please try again."));
			setSubmitError(message);
		} finally {
			setIsSubmittingLocal(false);
		}
	};

	// Non-field error from the parent (resource form), or a local submit
	// failure. Field errors display inline instead — unless the form
	// instance is unavailable (multi-step), where they land in the banner.
	const bannerMessage =
		errorMessage ??
		submitError ??
		(hasFieldErrors && !formInstance
			? Object.entries(serverFieldErrors)
					.map(
						([field, message]) =>
							`${field}: ${Array.isArray(message) ? message.join(", ") : message}`,
					)
					.join(" · ")
			: undefined);

	return (
		<div className="space-y-6">
			{/* Slug field */}
			<div className="space-y-2">
				<div className="flex items-center gap-2">
					<Label htmlFor="slug">
						{localization?.CMS_LABEL_SLUG ?? t("cms.common.slugLabel", "Slug")}
					</Label>
					{!isEditing && (
						<Badge variant="outline" className="text-xs">
							{slugManuallyEdited
								? (localization?.CMS_EDITOR_SLUG_MANUAL ??
									t("cms.editor.slugManual", "Manually set"))
								: (localization?.CMS_EDITOR_SLUG_AUTO ??
									t("cms.editor.slugAuto", "Auto-generated from first field"))}
						</Badge>
					)}
				</div>
				<Input
					id="slug"
					value={slug}
					onChange={(e) => {
						setSlug(e.target.value);
						setSlugError(null);
						if (!isEditing) {
							setSlugManuallyEdited(true);
						}
					}}
					disabled={isEditing}
					placeholder={
						slugSourceField
							? (
									localization?.CMS_EDITOR_SLUG_PLACEHOLDER_AUTO ??
									t(
										"cms.editor.slugPlaceholderAuto",
										"Auto-generated from {field}",
									)
								).replace("{field}", slugSourceField)
							: (localization?.CMS_EDITOR_SLUG_PLACEHOLDER ??
								t("cms.editor.slugPlaceholder", "Enter slug..."))
					}
				/>
				{slugError && <p className="text-sm text-destructive">{slugError}</p>}
				<p className="text-sm text-muted-foreground">
					{localization?.CMS_LABEL_SLUG_DESCRIPTION ??
						t(
							"cms.common.slugDescription",
							"URL-friendly identifier for this item",
						)}
				</p>
			</div>

			<div className="space-y-2">
				<Label htmlFor="publishAt">
					{t("cms.editor.publishAt", "Publish at")}
				</Label>
				<Input
					id="publishAt"
					type="datetime-local"
					value={publishAt}
					onChange={(event) => {
						aiPublishAtRef.current = undefined;
						publishAtEditedRef.current = true;
						setPublishAt(event.target.value);
					}}
					disabled={isSubmitting}
					aria-describedby="publishAt-description"
				/>
				<p id="publishAt-description" className="text-sm text-muted-foreground">
					{t(
						"cms.editor.publishAtDescription",
						"Optional. Uses your local time zone. Leave empty to clear the schedule.",
					)}
				</p>
				{serverFieldErrors.publishAt && (
					<p role="alert" className="text-sm text-destructive">
						{serverFieldErrors.publishAt}
					</p>
				)}
			</div>

			{/* Submit error message */}
			{bannerMessage && (
				<div className="rounded-md border border-destructive/50 bg-destructive/10 p-3">
					<p className="text-sm text-destructive">{bannerMessage}</p>
				</div>
			)}

			{/* Dynamic form from Zod schema */}
			{/* Uses SteppedAutoForm which automatically handles both single-step and multi-step content types */}
			<SteppedAutoForm
				formSchema={zodSchema as z.ZodObject<any, any>}
				values={formData as any}
				onValuesChange={handleValuesChange as any}
				onSubmit={handleSubmit as any}
				fieldConfig={fieldConfig as any}
				isSubmitting={isSubmitting}
				submitButtonText={
					isSubmitting
						? (localization?.CMS_STATUS_SAVING ??
							t("cms.common.saving", "Saving..."))
						: (localization?.CMS_BUTTON_SAVE ?? t("cms.common.save", "Save"))
				}
			>
				{onCancel && (
					<button
						type="button"
						onClick={onCancel}
						className="px-4 py-2 text-sm text-muted-foreground hover:text-foreground"
					>
						{localization?.CMS_BUTTON_CANCEL ??
							t("cms.common.cancel", "Cancel")}
					</button>
				)}
			</SteppedAutoForm>
		</div>
	);
}

"use client";

import {
	useState,
	useCallback,
	useEffect,
	type ChangeEvent,
	type ComponentType,
} from "react";
import {
	useNotify,
	usePluginOverrides,
	useTranslate,
} from "@btst/stack/context";
import type { CMSPluginOverrides } from "../../overrides";
import { CMS_PLUGIN_ID } from "../../constants";
import type { AutoFormInputComponentProps } from "@/components/ui/auto-form/types";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
	FormControl,
	FormItem,
	FormMessage,
} from "@/components/ui/form";
import { Trash2, Loader2 } from "lucide-react";
import AutoFormLabel from "@/components/ui/auto-form/common/label";
import AutoFormTooltip from "@/components/ui/auto-form/common/tooltip";

/**
 * Props for the CMSFileUpload component
 */
export interface CMSFileUploadProps extends AutoFormInputComponentProps {
	/**
	 * Function to upload an image file and return the URL.
	 * This is required - consumers must provide an upload implementation.
	 */
	uploadImage: (file: File) => Promise<string>;
	/**
	 * Optional custom component for the image field.
	 * When provided, it replaces the default file-upload input entirely.
	 */
	imageInputField?: ComponentType<{
		value: string;
		onChange: (value: string) => void;
		isRequired?: boolean;
	}>;
	/**
	 * Optional trigger component for a media picker.
	 * When provided, it is rendered as a "Browse media" option.
	 */
	imagePicker?: ComponentType<{ onSelect: (url: string) => void }>;
}

/**
 * Default file upload component for CMS image fields.
 *
 * This component:
 * - Accepts image files via file input
 * - Uses the required uploadImage prop to upload and get a URL
 * - Shows a preview of the uploaded image
 * - Allows removing the uploaded image
 *
 * You can use this component directly in your fieldComponents override,
 * or create your own custom component using this as a reference.
 *
 * @example
 * ```tsx
 * // Use the default component with your upload function
 * fieldComponents: {
 *   file: (props) => (
 *     <CMSFileUpload {...props} uploadImage={myUploadFn} />
 *   ),
 * }
 * ```
 */
export function CMSFileUpload({
	label,
	isRequired,
	fieldConfigItem,
	fieldProps,
	field,
	uploadImage,
	imageInputField: ImageInputField,
	imagePicker: ImagePickerTrigger,
}: CMSFileUploadProps) {
	// Exclude showLabel and value from props spread
	// File inputs cannot have their value set programmatically (browser security)
	const {
		showLabel: _showLabel,
		value: _value,
		...safeFieldProps
	} = fieldProps;
	const showLabel = _showLabel === undefined ? true : _showLabel;

	// All hooks must be called unconditionally before any early return.
	const t = useTranslate();
	const notify = useNotify();
	const { localization } =
		usePluginOverrides<CMSPluginOverrides>(CMS_PLUGIN_ID);
	const [isUploading, setIsUploading] = useState(false);
	const [previewUrl, setPreviewUrl] = useState<string | null>(
		field.value || null,
	);

	useEffect(() => {
		const normalizedValue = field.value || null;
		if (normalizedValue !== previewUrl) {
			setPreviewUrl(normalizedValue);
		}
	}, [field.value, previewUrl]);

	const handleFileChange = useCallback(
		async (e: ChangeEvent<HTMLInputElement>) => {
			const file = e.target.files?.[0];
			if (!file) return;

			if (!file.type.startsWith("image/")) {
				notify.error(
					localization?.CMS_EDITOR_FILE_INVALID_TYPE ??
						t("cms.editor.fileInvalidType", "Please select an image file"),
				);
				return;
			}

			setIsUploading(true);
			try {
				const url = await uploadImage(file);
				setPreviewUrl(url);
				field.onChange(url);
			} catch (error) {
				console.error("Image upload failed:", error);
				notify.error(
					localization?.CMS_EDITOR_FILE_UPLOAD_FAILED ??
						t("cms.editor.fileUploadFailed", "Failed to upload image"),
				);
			} finally {
				setIsUploading(false);
			}
		},
		[field, uploadImage, notify, localization, t],
	);

	const handleRemove = useCallback(() => {
		setPreviewUrl(null);
		field.onChange("");
	}, [field]);

	// When a custom imageInputField component is provided via overrides, delegate to it.
	if (ImageInputField) {
		return (
			<FormItem>
				{showLabel && (
					<AutoFormLabel
						label={fieldConfigItem?.label || label}
						isRequired={isRequired}
					/>
				)}
				<FormControl>
					<ImageInputField
						value={field.value || ""}
						onChange={field.onChange}
						isRequired={isRequired}
					/>
				</FormControl>
				<AutoFormTooltip fieldConfigItem={fieldConfigItem} />
				<FormMessage />
			</FormItem>
		);
	}

	return (
		<FormItem>
			{showLabel && (
				<AutoFormLabel
					label={fieldConfigItem?.label || label}
					isRequired={isRequired}
				/>
			)}
			{!previewUrl && (
				<FormControl>
					<div className="space-y-2">
						<div className="relative">
							<Input
								type="file"
								accept="image/*"
								{...safeFieldProps}
								onChange={handleFileChange}
								disabled={isUploading}
								className="cursor-pointer"
								data-testid="image-upload-input"
							/>
							{isUploading && (
								<div className="absolute inset-0 flex items-center justify-center bg-background/80">
									<Loader2 className="h-4 w-4 animate-spin" />
								</div>
							)}
						</div>
						{ImagePickerTrigger && (
							<div data-testid="image-picker-trigger">
								<ImagePickerTrigger
									onSelect={(url: string) => {
										setPreviewUrl(url);
										field.onChange(url);
									}}
								/>
							</div>
						)}
					</div>
				</FormControl>
			)}
			{previewUrl && (
				<div className="flex items-center gap-2">
					<div className="relative h-20 w-20 overflow-hidden rounded-md border">
						<img
							src={previewUrl}
							alt="Preview"
							className="h-full w-full object-cover"
							data-testid="image-preview"
						/>
					</div>
					<Button
						type="button"
						variant="outline"
						size="sm"
						onClick={handleRemove}
						className="flex items-center gap-1"
						data-testid="remove-image-button"
					>
						<Trash2 className="h-4 w-4" />
						Remove
					</Button>
				</div>
			)}
			<AutoFormTooltip fieldConfigItem={fieldConfigItem} />
			<FormMessage />
		</FormItem>
	);
}

"use client";

import { useState, useCallback, useMemo } from "react";
import { usePluginOverrides, useTranslate } from "@btst/stack/context";
import { useCreateContent, useContentOptions } from "@btst/plugin-cms/client/hooks";
import type { SerializedContentItemWithType } from "../../../types";
import type { CMSPluginOverrides } from "../../overrides";
import { CMS_PLUGIN_ID } from "../../constants";
import MultipleSelector from "@/components/ui/multi-select";
import type { Option } from "@/components/ui/multi-select";
import { Button } from "@/components/ui/button";
import { Plus, X } from "lucide-react";
import {
	Dialog,
	DialogContent,
	DialogHeader,
	DialogTitle,
	DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import type { AutoFormInputComponentProps } from "@/components/ui/auto-form/types";
import type { RelationConfig } from "../../../types";

interface RelationFieldProps extends AutoFormInputComponentProps {
	relation: RelationConfig;
}

/**
 * A form field component for handling CMS content relationships.
 * Supports selecting existing items and optionally creating new items inline.
 *
 * Options come from the resource `useSelect` hook: debounced server-side
 * search over the target type, with selected values not present in the
 * current results preloaded by id (for labels).
 *
 * Handles two value formats:
 * - belongsTo: single object { id: string } or undefined
 * - hasMany/manyToMany: array of { id: string }
 */
export function RelationField({
	field,
	fieldConfigItem,
	label,
	isRequired,
	relation,
}: RelationFieldProps) {
	const t = useTranslate();
	const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
	const [newItemName, setNewItemName] = useState("");
	const [newItemDescription, setNewItemDescription] = useState("");
	const [createError, setCreateError] = useState<string | null>(null);

	const { localization } =
		usePluginOverrides<CMSPluginOverrides>(CMS_PLUGIN_ID);

	// For belongsTo (single relation), we only allow one selection
	const isSingleSelect = relation.type === "belongsTo";

	// Normalize the field value to an array for internal use
	// belongsTo stores as single object { id }, hasMany/manyToMany store as array
	const normalizedValue = useMemo((): Array<{ id: string }> => {
		if (!field.value) return [];

		if (isSingleSelect) {
			// belongsTo: value is { id: string } or undefined
			const singleValue = field.value as { id?: string } | undefined;
			if (singleValue && singleValue.id) {
				return [{ id: singleValue.id }];
			}
			return [];
		}

		// hasMany/manyToMany: value is array
		return (field.value as Array<{ id: string }>) || [];
	}, [field.value, isSingleSelect]);

	const { displayField } = relation;
	const getOptionLabel = useCallback(
		(item: SerializedContentItemWithType) =>
			String(
				(item.parsedData as Record<string, unknown>)?.[displayField] ||
					item.slug,
			),
		[displayField],
	);

	const select = useContentOptions({
		targetType: relation.targetType,
		value: normalizedValue.map((v) => v.id),
		getOptionLabel,
	});

	const options: Option[] = select.options.map((option) => ({
		value: option.value,
		label: option.label,
	}));
	const selectedOptions: Option[] = select.selectedOptions.map((option) => ({
		value: option.value,
		label: option.label,
	}));

	// Mutation for creating new items
	const createMutation = useCreateContent(relation.targetType);

	// Handle selection change - convert back to appropriate format
	const handleChange = useCallback(
		(newOptions: Option[]) => {
			if (isSingleSelect) {
				// belongsTo: store as single object or undefined
				if (newOptions.length > 0) {
					field.onChange({ id: newOptions[0]!.value });
				} else {
					field.onChange(undefined);
				}
			} else {
				// hasMany/manyToMany: store as array
				const newValue = newOptions.map((opt) => ({ id: opt.value }));
				field.onChange(newValue);
			}
		},
		[field, isSingleSelect],
	);

	// Handle creating a new item
	const handleCreateItem = async () => {
		if (!newItemName.trim()) return;

		setCreateError(null);
		try {
			const result = await createMutation.mutateAsync({
				slug: newItemName.toLowerCase().replace(/\s+/g, "-"),
				data: {
					[relation.displayField]: newItemName,
					description: newItemDescription || undefined,
				} as Record<string, unknown>,
			});

			// Add the new item to the selection
			if (isSingleSelect) {
				// belongsTo: replace with new item
				field.onChange({ id: result.id });
			} else {
				// hasMany/manyToMany: append to array
				const newValue = [...normalizedValue, { id: result.id }];
				field.onChange(newValue);
			}

			// Reset and close dialog
			setNewItemName("");
			setNewItemDescription("");
			setIsCreateDialogOpen(false);
		} catch (error) {
			const message =
				error instanceof Error
					? error.message
					: (localization?.CMS_RELATION_CREATE_ERROR ??
						t(
							"cms.relations.createError",
							"Failed to create item. Please try again.",
						));
			setCreateError(message);
		}
	};

	// Handle removing an item
	const handleRemove = useCallback(
		(idToRemove: string) => {
			if (isSingleSelect) {
				// belongsTo: clear the value
				field.onChange(undefined);
			} else {
				// hasMany/manyToMany: filter out the item
				const newValue = normalizedValue.filter((v) => v.id !== idToRemove);
				field.onChange(newValue);
			}
		},
		[normalizedValue, field, isSingleSelect],
	);

	const displayFieldLabel =
		relation.displayField.charAt(0).toUpperCase() +
		relation.displayField.slice(1);

	return (
		<div className="space-y-2">
			<Label>
				{label}
				{isRequired && <span className="text-destructive ml-1">*</span>}
			</Label>

			<div className="flex gap-2">
				<div className="flex-1">
					<MultipleSelector
						value={selectedOptions}
						onChange={handleChange}
						options={options}
						placeholder={
							select.isLoading
								? (localization?.CMS_RELATION_LOADING ??
									t("cms.relations.loading", "Loading..."))
								: (isSingleSelect
										? (localization?.CMS_RELATION_SELECT_PLACEHOLDER ??
											t(
												"cms.relations.selectPlaceholder",
												"Select {targetType}...",
											))
										: (localization?.CMS_RELATION_SELECT_PLACEHOLDER_MULTI ??
											t(
												"cms.relations.selectPlaceholderMulti",
												"Select {targetType}(s)...",
											))
									).replace("{targetType}", relation.targetType)
						}
						disabled={select.isLoading}
						hidePlaceholderWhenSelected
						// Options are server-filtered (search param); disable the
						// built-in client-side filtering so results aren't re-filtered
						// against an incomplete option set.
						commandProps={{ shouldFilter: false }}
						inputProps={{ onValueChange: select.setSearch }}
						emptyIndicator={
							<p className="text-center text-sm text-muted-foreground py-4">
								{(
									localization?.CMS_RELATION_EMPTY ??
									t("cms.relations.empty", "No {targetType} items found")
								).replace("{targetType}", relation.targetType)}
							</p>
						}
						maxSelected={isSingleSelect ? 1 : undefined}
						className="min-h-10"
					/>
				</div>

				{/* Create new item button/dialog */}
				{relation.creatable && (
					<Dialog
						open={isCreateDialogOpen}
						onOpenChange={setIsCreateDialogOpen}
					>
						<DialogTrigger asChild>
							<Button type="button" variant="outline" size="icon">
								<Plus className="h-4 w-4" />
							</Button>
						</DialogTrigger>
						<DialogContent>
							<DialogHeader>
								<DialogTitle>
									{(
										localization?.CMS_RELATION_CREATE_TITLE ??
										t("cms.relations.createTitle", "Create New {targetType}")
									).replace("{targetType}", relation.targetType)}
								</DialogTitle>
							</DialogHeader>
							<div className="space-y-4 py-4">
								{createError && (
									<p className="text-sm text-destructive">{createError}</p>
								)}
								<div className="space-y-2">
									<Label htmlFor="newItemName">{displayFieldLabel}</Label>
									<Input
										id="newItemName"
										value={newItemName}
										onChange={(e) => setNewItemName(e.target.value)}
										placeholder={(
											localization?.CMS_RELATION_NAME_PLACEHOLDER ??
											t("cms.relations.namePlaceholder", "Enter {field}...")
										).replace("{field}", relation.displayField)}
									/>
								</div>
								<div className="space-y-2">
									<Label htmlFor="newItemDescription">
										{localization?.CMS_RELATION_DESCRIPTION_LABEL ??
											t(
												"cms.relations.descriptionLabel",
												"Description (optional)",
											)}
									</Label>
									<Textarea
										id="newItemDescription"
										value={newItemDescription}
										onChange={(e) => setNewItemDescription(e.target.value)}
										placeholder={
											localization?.CMS_RELATION_DESCRIPTION_PLACEHOLDER ??
											t(
												"cms.relations.descriptionPlaceholder",
												"Enter description...",
											)
										}
										rows={3}
									/>
								</div>
								<div className="flex justify-end gap-2">
									<Button
										type="button"
										variant="outline"
										onClick={() => setIsCreateDialogOpen(false)}
									>
										{localization?.CMS_BUTTON_CANCEL ??
											t("cms.common.cancel", "Cancel")}
									</Button>
									<Button
										type="button"
										onClick={handleCreateItem}
										disabled={!newItemName.trim() || createMutation.isPending}
									>
										{createMutation.isPending
											? (localization?.CMS_RELATION_CREATING ??
												t("cms.relations.creating", "Creating..."))
											: (localization?.CMS_RELATION_CREATE_BUTTON ??
												t("cms.relations.createButton", "Create"))}
									</Button>
								</div>
							</div>
						</DialogContent>
					</Dialog>
				)}
			</div>

			{/* Show selected items as removable badges */}
			{selectedOptions.length > 0 && (
				<div className="flex flex-wrap gap-1 mt-2">
					{selectedOptions.map((opt) => (
						<div
							key={opt.value}
							className="inline-flex items-center gap-1 px-2 py-1 text-xs rounded-md bg-secondary text-secondary-foreground"
						>
							<span>{opt.label}</span>
							<button
								type="button"
								onClick={() => handleRemove(opt.value)}
								className="hover:text-destructive"
							>
								<X className="h-3 w-3" />
							</button>
						</div>
					))}
				</div>
			)}

			{fieldConfigItem?.description && (
				<p className="text-sm text-muted-foreground">
					{fieldConfigItem.description}
				</p>
			)}
		</div>
	);
}

"use client";

import { useState } from "react";
import {
	ChevronDown,
	ChevronRight,
	ExternalLink,
	Plus,
	Trash2,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
	Card,
	CardContent,
	CardHeader,
	CardTitle,
} from "@/components/ui/card";
import {
	joinBasePath,
	PermissionAccess,
	usePluginOverrides,
	useStack,
	useTranslate,
	type TranslateFn,
} from "@btst/stack/context";
import { cmsPermissions } from "../../permissions";
import {
	useDeleteContent,
	useInverseRelations,
	useInverseRelationItems,
} from "@btst/plugin-cms/client/hooks";
import type { CMSPluginOverrides } from "../overrides";
import { CMS_PLUGIN_ID } from "../constants";
import type {
	InverseRelation,
	SerializedContentItemWithType,
} from "../../types";
import {
	AlertDialog,
	AlertDialogAction,
	AlertDialogCancel,
	AlertDialogContent,
	AlertDialogDescription,
	AlertDialogFooter,
	AlertDialogHeader,
	AlertDialogTitle,
} from "@/components/ui/alert-dialog";

interface InverseRelationsPanelProps {
	contentTypeSlug: string;
	itemId: string;
}

/**
 * Panel that shows content items that reference this item via belongsTo relations.
 * For example, when editing a Resource, this shows all Comments that belong to it.
 */
export function InverseRelationsPanel({
	contentTypeSlug,
	itemId,
}: InverseRelationsPanelProps) {
	const t = useTranslate();
	const { localization } =
		usePluginOverrides<CMSPluginOverrides>(CMS_PLUGIN_ID);
	const { router, plugins, basePath: stackBasePath } = useStack();
	const navigate = router?.navigate;
	const Link = router?.Link;
	const basePath = plugins?.[CMS_PLUGIN_ID]?.site.basePath ?? stackBasePath;

	// Fetch inverse relations metadata
	const { inverseRelations, isLoading } = useInverseRelations(
		contentTypeSlug,
		itemId,
	);

	if (isLoading) {
		return (
			<Card className="animate-pulse">
				<CardHeader>
					<div className="h-5 w-32 bg-muted rounded" />
				</CardHeader>
			</Card>
		);
	}

	if (inverseRelations.length === 0) {
		return null;
	}

	// When a single source content type has multiple belongsTo fields pointing
	// at this target type (e.g. StackSynergy has both compoundAId and
	// compoundBId → compound), the section title alone ("Stack Synergy") is
	// ambiguous — two cards would render with identical headings. Mark those
	// relations so we can disambiguate them by field name.
	const sourceTypeCounts = new Map<string, number>();
	for (const rel of inverseRelations) {
		sourceTypeCounts.set(
			rel.sourceType,
			(sourceTypeCounts.get(rel.sourceType) ?? 0) + 1,
		);
	}

	return (
		<div className="space-y-4">
			<h3 className="text-lg font-semibold">
				{localization?.CMS_RELATED_ITEMS_TITLE ??
					t("cms.relations.relatedItemsTitle", "Related Items")}
			</h3>
			{inverseRelations.map((relation) => (
				<InverseRelationSection
					key={`${relation.sourceType}-${relation.fieldName}`}
					relation={relation}
					contentTypeSlug={contentTypeSlug}
					itemId={itemId}
					basePath={basePath}
					navigate={navigate}
					Link={Link}
					localization={localization}
					t={t}
					ambiguous={(sourceTypeCounts.get(relation.sourceType) ?? 0) > 1}
				/>
			))}
		</div>
	);
}

/**
 * Turn a relation field name like `compoundAId` / `categoryIds` into a
 * friendlier label like `Compound A` / `Category` for display in the
 * inverse-relations panel when two sections would otherwise share a title.
 *
 * Strips a trailing `Id` or `Ids`, splits camelCase boundaries, and
 * title-cases the result. Leaves unrecognised shapes as-is so we never
 * produce an empty string.
 */
function humanizeFieldName(fieldName: string): string {
	const stripped = fieldName.replace(/Ids?$/, "") || fieldName;
	const words = stripped
		.replace(/([a-z0-9])([A-Z])/g, "$1 $2")
		.replace(/[_-]+/g, " ")
		.trim()
		.split(/\s+/);
	return words.map((w) => (w ? w[0]!.toUpperCase() + w.slice(1) : w)).join(" ");
}

interface InverseRelationSectionProps {
	relation: InverseRelation;
	contentTypeSlug: string;
	itemId: string;
	basePath: string;
	navigate?: (path: string) => void | Promise<void>;
	Link?: React.ComponentType<{
		href?: string;
		children?: React.ReactNode;
		className?: string;
	}>;
	localization: CMSPluginOverrides["localization"];
	t: TranslateFn;
	/**
	 * True when another inverse relation from the same `sourceType` is also
	 * being rendered — in which case the field-name suffix is shown so the
	 * user can tell the two cards apart.
	 */
	ambiguous: boolean;
}

function InverseRelationSection({
	relation,
	contentTypeSlug,
	itemId,
	basePath,
	navigate,
	Link,
	localization,
	t,
	ambiguous,
}: InverseRelationSectionProps) {
	const [isExpanded, setIsExpanded] = useState(true);
	const [deleteItemId, setDeleteItemId] = useState<string | null>(null);
	const [deleteError, setDeleteError] = useState<string | null>(null);
	const deleteContent = useDeleteContent(relation.sourceType);

	// Fetch items for this inverse relation
	const {
		items,
		total: fetchedTotal,
		refetch,
	} = useInverseRelationItems(
		{
			contentTypeSlug,
			sourceType: relation.sourceType,
			itemId,
			fieldName: relation.fieldName,
		},
		{ enabled: isExpanded },
	);

	const total = fetchedTotal || relation.count;

	const handleDelete = async () => {
		if (deleteItemId) {
			setDeleteError(null);
			try {
				await deleteContent.mutateAsync(deleteItemId);
				setDeleteItemId(null);
				void refetch();
			} catch (error) {
				const message =
					error instanceof Error
						? error.message
						: (localization?.CMS_RELATED_DELETE_ERROR ??
							t(
								"cms.relations.relatedDeleteError",
								"Failed to delete item. Please try again.",
							));
				setDeleteError(message);
			}
		}
	};

	// Create new item with pre-filled belongsTo field
	const handleAddNew = () => {
		// Navigate to create page with query param to pre-fill the relation.
		// ContentEditorPage reads prefill_* query params and passes them to ContentForm as initialData.
		const createUrl = joinBasePath(
			basePath,
			`/cms/${relation.sourceType}/new?prefill_${relation.fieldName}=${itemId}`,
		);
		void navigate?.(createUrl);
	};

	const LinkComponent = Link ?? "a";
	const fieldLabel = ambiguous ? humanizeFieldName(relation.fieldName) : null;

	return (
		<Card>
			<CardHeader className="py-3">
				<button
					type="button"
					onClick={() => setIsExpanded(!isExpanded)}
					className="flex items-center justify-between w-full text-left"
				>
					<CardTitle className="text-base flex items-center gap-2">
						{isExpanded ? (
							<ChevronDown className="h-4 w-4" />
						) : (
							<ChevronRight className="h-4 w-4" />
						)}
						<span>{relation.sourceTypeName}</span>
						{fieldLabel && (
							<span className="font-normal text-muted-foreground">
								· {fieldLabel}
							</span>
						)}
						<span className="font-normal text-muted-foreground">({total})</span>
					</CardTitle>
				</button>
			</CardHeader>
			{isExpanded && (
				<CardContent className="pt-0">
					{items.length === 0 ? (
						<p className="text-sm text-muted-foreground py-2">
							{(
								localization?.CMS_RELATED_EMPTY ??
								t(
									"cms.relations.relatedEmpty",
									"No {sourceTypeName} items yet.",
								)
							).replace(
								"{sourceTypeName}",
								relation.sourceTypeName.toLowerCase(),
							)}
						</p>
					) : (
						<ul className="space-y-2">
							{items.map((item: SerializedContentItemWithType) => {
								const displayValue = getDisplayValue(item);
								const editUrl = joinBasePath(
									basePath,
									`/cms/${relation.sourceType}/${item.id}`,
								);
								return (
									<li
										key={item.id}
										className="flex items-center justify-between py-2 px-3 rounded-md bg-muted/50 hover:bg-muted transition-colors"
									>
										<LinkComponent
											href={editUrl}
											className="flex-1 text-sm hover:underline flex items-center gap-2"
										>
											<span className="truncate">{displayValue}</span>
											<ExternalLink className="h-3 w-3 opacity-50" />
										</LinkComponent>
										<PermissionAccess
											permission={cmsPermissions.record.delete({
												contentType:
													item.contentType?.slug ?? relation.sourceType,
												recordId: item.id,
												...(item.authorId ? { authorId: item.authorId } : {}),
											})}
										>
											<Button
												variant="ghost"
												size="icon"
												className="h-7 w-7 text-muted-foreground hover:text-destructive"
												onClick={() => setDeleteItemId(item.id)}
											>
												<Trash2 className="h-3.5 w-3.5" />
											</Button>
										</PermissionAccess>
									</li>
								);
							})}
						</ul>
					)}
					<div className="mt-3 pt-3 border-t">
						<PermissionAccess
							permission={cmsPermissions.record.create({
								contentType: relation.sourceType,
							})}
						>
							<Button
								variant="outline"
								size="sm"
								onClick={handleAddNew}
								className="w-full"
							>
								<Plus className="h-4 w-4 mr-2" />
								{(
									localization?.CMS_RELATED_ADD ??
									t("cms.relations.relatedAdd", "Add {sourceTypeName}")
								).replace("{sourceTypeName}", relation.sourceTypeName)}
								{fieldLabel ? ` (${fieldLabel})` : ""}
							</Button>
						</PermissionAccess>
					</div>
				</CardContent>
			)}

			{/* Delete confirmation dialog */}
			<AlertDialog
				open={!!deleteItemId}
				onOpenChange={(open) => {
					if (!open) {
						setDeleteItemId(null);
						setDeleteError(null);
					}
				}}
			>
				<AlertDialogContent>
					<AlertDialogHeader>
						<AlertDialogTitle>
							{(
								localization?.CMS_RELATED_DELETE_TITLE ??
								t(
									"cms.relations.relatedDeleteTitle",
									"Delete {sourceTypeName}?",
								)
							).replace("{sourceTypeName}", relation.sourceTypeName)}
						</AlertDialogTitle>
						<AlertDialogDescription>
							{(
								localization?.CMS_RELATED_DELETE_DESCRIPTION ??
								t(
									"cms.relations.relatedDeleteDescription",
									"This action cannot be undone. This will permanently delete this {sourceTypeName}.",
								)
							).replace(
								"{sourceTypeName}",
								relation.sourceTypeName.toLowerCase(),
							)}
						</AlertDialogDescription>
					</AlertDialogHeader>
					{deleteError && (
						<p className="text-sm text-destructive">{deleteError}</p>
					)}
					<AlertDialogFooter>
						<AlertDialogCancel>
							{localization?.CMS_BUTTON_CANCEL ??
								t("cms.common.cancel", "Cancel")}
						</AlertDialogCancel>
						<AlertDialogAction
							onClick={handleDelete}
							className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
						>
							{localization?.CMS_BUTTON_DELETE ??
								t("cms.common.delete", "Delete")}
						</AlertDialogAction>
					</AlertDialogFooter>
				</AlertDialogContent>
			</AlertDialog>
		</Card>
	);
}

/**
 * Get a display value from an item's parsedData
 */
function getDisplayValue(item: SerializedContentItemWithType): string {
	const data = item.parsedData as Record<string, unknown>;
	// Try common display fields
	const displayFields = ["name", "title", "label", "content", "author", "slug"];
	for (const field of displayFields) {
		if (typeof data[field] === "string" && data[field]) {
			const value = data[field] as string;
			return value.length > 50 ? `${value.slice(0, 50)}...` : value;
		}
	}
	return item.slug;
}

"use client";

import { Skeleton } from "@/components/ui/skeleton";
import { PageWrapper } from "../shared/page-wrapper";

export function DashboardSkeleton() {
	return (
		<PageWrapper testId="cms-dashboard-skeleton">
			<div className="w-full max-w-5xl space-y-6">
				<div className="space-y-2">
					<Skeleton className="h-8 w-48" />
					<Skeleton className="h-4 w-64" />
				</div>
