/**
 * Parse prefill query parameters from the URL.
 * Looks for query params with the format `prefill_<fieldName>=<value>`
 * and returns a record of field names to values.
 *
 * Uses useState + useEffect pattern to work correctly with SSR/hydration.
 * During SSR, returns empty object. After hydration, parses URL params.
 * Also listens for popstate events to handle browser back/forward navigation.
 *
 * @example
 * URL: /cms/comment/new?prefill_resourceId=123&prefill_author=John
 * Returns: { resourceId: "123", author: "John" }
 */
function usePrefillParams(): Record<string, string> {
	const [prefillData, setPrefillData] = useState<Record<string, string>>({});

	useEffect(() => {
		if (typeof window === "undefined") {
			return;
		}

		const parseAndSetPrefillData = () => {
			const params = new URLSearchParams(window.location.search);
			const data: Record<string, string> = {};

			for (const [key, value] of params.entries()) {
				if (key.startsWith("prefill_")) {
					const fieldName = key.slice("prefill_".length);
					if (fieldName) {
						data[fieldName] = value;
					}
				}
			}

			// Always update state to ensure stale data is cleared when navigating
			// to a URL without prefill params (e.g., via browser back/forward)
			setPrefillData(data);
		};

		// Parse on mount
		parseAndSetPrefillData();

		// Listen for popstate events (browser back/forward navigation)
		window.addEventListener("popstate", parseAndSetPrefillData);

		return () => {
			window.removeEventListener("popstate", parseAndSetPrefillData);
		};
	}, []);

	return prefillData;
}

interface JsonSchemaProperty {
	fieldType?: string;
	relation?: {
		type: "belongsTo" | "hasMany" | "manyToMany";
		targetType: string;
	};
}

/**
 * Convert prefill params to the correct format for the form.
 * Relation fields need special handling:
 * - belongsTo: value should be { id: "uuid" }
 * - hasMany/manyToMany: value should be [{ id: "uuid" }]
 *
 * @param prefillParams - Raw prefill params from URL
 * @param jsonSchema - The content type's JSON schema
 * @returns Converted data suitable for initialData
 */
function convertPrefillToFormData(
	prefillParams: Record<string, string>,
	jsonSchema: Record<string, unknown>,
): Record<string, unknown> {
	const properties = jsonSchema.properties as
		| Record<string, JsonSchemaProperty>
		| undefined;

	if (!properties) {
		return prefillParams;
	}

	const result: Record<string, unknown> = {};

	for (const [fieldName, value] of Object.entries(prefillParams)) {
		const fieldSchema = properties[fieldName];

		if (fieldSchema?.fieldType === "relation" && fieldSchema.relation) {
			// Convert relation field value to the correct format
			if (fieldSchema.relation.type === "belongsTo") {
				// belongsTo expects { id: "uuid" }
				result[fieldName] = { id: value };
			} else {
				// hasMany/manyToMany expect [{ id: "uuid" }]
				result[fieldName] = [{ id: value }];
			}
		} else {
			// Non-relation fields: pass through as-is
			result[fieldName] = value;
		}
	}

	return result;
}

interface ContentEditorPageProps {
	typeSlug: string;
	id?: string;
}

export function ContentEditorPage({ typeSlug, id }: ContentEditorPageProps) {
	const t = useTranslate();
	const overrides = usePluginOverrides<CMSPluginOverrides>(CMS_PLUGIN_ID);
	const { localization } = overrides;
	const { router, plugins, basePath: stackBasePath } = useStack();
	const navigate = router?.navigate;
	const basePath = plugins?.[CMS_PLUGIN_ID]?.site.basePath ?? stackBasePath;

	// Parse prefill query parameters for pre-populating fields when creating new items
	// This is used by the inverse relations panel to pre-fill the parent relation
	const prefillParams = usePrefillParams();

	// Call route lifecycle hooks for telemetry and application behavior.
	useRouteLifecycle({
		routeName: "contentEditor",
		context: {
			path: id ? `/cms/${typeSlug}/${id}` : `/cms/${typeSlug}/new`,
			params: id ? { typeSlug, id } : { typeSlug },
			isSSR: typeof window === "undefined",
		},
		overrides,
	});

	const { contentTypes: serverContentTypes } = useSuspenseContentTypes();
	const contentTypes = orderCMSContentTypes(
		serverContentTypes,
		plugins?.[CMS_PLUGIN_ID]?.config,
	);
	const contentType = contentTypes.find((ct) => ct.slug === typeSlug);

	const isEditing = !!id;
	const [restoreCount, setRestoreCount] = useState(0);

	// useContentItem has enabled: !!id built-in, so it won't fetch when creating new items
	// This avoids conditional hook calls which violate React's Rules of Hooks
	const { item, isLoading: isLoadingItem } = useContentItem(typeSlug, id ?? "");

	// Core resource form: submits the right mutation, awaits invalidation,
	// notifies success/error via useNotify(), and exposes server validation
	// issues as fieldErrors for inline display.
	const resourceForm = useContentItemForm<{
		slug: string;
		data: Record<string, unknown>;
		publishAt?: string | null;
	}>({
		action: isEditing ? "edit" : "create",
		record: isEditing ? item : null,
		successMessage: (_result, action) =>
			action === "create"
				? (localization?.CMS_TOAST_CREATE_SUCCESS ??
					t("cms.toasts.createSuccess", "Item created successfully"))
				: (localization?.CMS_TOAST_UPDATE_SUCCESS ??
					t("cms.toasts.updateSuccess", "Item updated successfully")),
		toCreateVars: (values) => ({
			typeSlug,
			slug: values.slug,
			data: values.data,
			publishAt: values.publishAt,
		}),
		toUpdateVars: (values) => ({
			typeSlug,
			id: id ?? "",
			data: {
				slug: values.slug,
				data: values.data,
				publishAt: values.publishAt,
			},
		}),
		onSuccess: () => {
			void navigate?.(joinBasePath(basePath, `/cms/${typeSlug}`));
		},
	});

	if (!contentType) {
		return (
			<PageWrapper testId="cms-editor-page">
				<div className="w-full max-w-2xl">
					<EmptyState
						title={
							localization?.CMS_ERROR_NOT_FOUND ??
							t("cms.common.notFound", "Not found")
						}
						description={
							localization?.CMS_ERROR_TYPE_NOT_FOUND_DESCRIPTION ??
							t("cms.common.typeNotFoundDescription", "Content type not found")
						}
					/>
				</div>
			</PageWrapper>
		);
	}

	// Show loading skeleton while fetching item in edit mode
	if (isEditing && isLoadingItem) {
		return (
			<PageWrapper testId="cms-editor-page">
				<div className="w-full max-w-2xl">
					<EditorSkeleton />
				</div>
			</PageWrapper>
		);
	}

	if (isEditing && !item) {
		return (
			<PageWrapper testId="cms-editor-page">
				<div className="w-full max-w-2xl">
					<EmptyState
						title={
							localization?.CMS_ERROR_NOT_FOUND ??
							t("cms.common.notFound", "Not found")
						}
						description={
							localization?.CMS_ERROR_ITEM_NOT_FOUND_DESCRIPTION ??
							t("cms.common.itemNotFoundDescription", "Content item not found")
						}
					/>
				</div>
			</PageWrapper>
		);
	}

	// resourceForm.submit never throws: success notifies + navigates via the
	// config above; errors land on resourceForm.error / fieldErrors.
	const handleSubmit = async (data: {
		slug: string;
		data: Record<string, unknown>;
	}) => {
		await resourceForm.submit(data);
	};

	const hasFieldErrors = Object.keys(resourceForm.fieldErrors).length > 0;

	const title = isEditing
		? (
				localization?.CMS_EDITOR_TITLE_EDIT ??
				t("cms.editor.titleEdit", "Edit {typeName}")
			).replace("{typeName}", contentType.name)
		: (
				localization?.CMS_EDITOR_TITLE_NEW ??
				t("cms.editor.titleNew", "New {typeName}")
			).replace("{typeName}", contentType.name);

	return (
		<PageWrapper testId="cms-editor-page">
			<div className="w-full max-w-2xl space-y-6">
				<div className="flex flex-wrap items-center gap-4">
					<Button
						variant="ghost"
						size="icon"
						onClick={() =>
							void navigate?.(joinBasePath(basePath, `/cms/${typeSlug}`))
						}
					>
						<ArrowLeft className="h-4 w-4" />
					</Button>
					<h1 className="text-2xl font-bold tracking-tight">{title}</h1>
					{isEditing && id && (
						<RevisionHistory
							typeSlug={typeSlug}
							itemId={id}
							onRestored={() => setRestoreCount((count) => count + 1)}
						/>
					)}
				</div>

				<ContentForm
					key={isEditing ? `edit-${id}-${restoreCount}` : "create"}
					contentType={contentType}
					initialData={
						isEditing
							? (item?.parsedData ?? undefined)
							: Object.keys(prefillParams).length > 0
								? convertPrefillToFormData(
										prefillParams,
										JSON.parse(contentType.jsonSchema),
									)
								: undefined
					}
					initialSlug={item?.slug}
					initialPublishAt={item?.publishAt}
					isEditing={isEditing}
					onSubmit={handleSubmit}
					onCancel={() =>
						void navigate?.(joinBasePath(basePath, `/cms/${typeSlug}`))
					}
					fieldErrors={resourceForm.fieldErrors}
					errorMessage={
						hasFieldErrors ? undefined : resourceForm.error?.message
					}
					isSubmitting={resourceForm.isSubmitting}
				/>

				{/* Show inverse relations panel when editing (not creating) */}
				{isEditing && id && (
					<InverseRelationsPanel contentTypeSlug={typeSlug} itemId={id} />
				)}
			</div>
		</PageWrapper>
	);
}

"use client";

import { lazy } from "react";
import { usePluginOverrides } from "@btst/stack/context";
import type { CMSPluginOverrides } from "../../overrides";
import { CMS_PLUGIN_ID } from "../../constants";
import {
	ComposedRoute,
	PermissionRouteAccess,
} from "@btst/stack/client/components";
import { DefaultError } from "../shared/default-error";
import { EditorSkeleton } from "../loading";
import { NotFoundPage } from "./404-page";
import { cmsPermissions } from "../../../permissions";
import { useSuspenseContentItem } from "@btst/plugin-cms/client/hooks";

const ContentEditorPageInternal = lazy(() =>
	import("./content-editor-page.internal").then((m) => ({
		default: m.ContentEditorPage,
	})),
);

interface ContentEditorPageComponentProps {
	typeSlug: string;
	id?: string;
}

export function ContentEditorPageComponent({
	typeSlug,
	id,
}: ContentEditorPageComponentProps) {
	const { onRouteError } =
		usePluginOverrides<CMSPluginOverrides>(CMS_PLUGIN_ID);

	const isNew = !id;
	const path = isNew ? `/cms/${typeSlug}/new` : `/cms/${typeSlug}/${id}`;

	return (
		<ComposedRoute
			path={path}
			PageComponent={AuthorizedContentEditorPage}
			ErrorComponent={DefaultError}
			LoadingComponent={EditorSkeleton}
			NotFoundComponent={NotFoundPage}
			props={{ typeSlug, id }}
			onError={(error) => {
				if (onRouteError) {
					onRouteError("contentEditor", error, {
						path,
						params: { typeSlug, id: id ?? "" },
						isSSR: typeof window === "undefined",
					});
				}
			}}
		/>
	);
}

function AuthorizedContentEditorPage({
	typeSlug,
	id,
}: ContentEditorPageComponentProps) {
	if (!id) {
		return (
			<PermissionRouteAccess
				permission={cmsPermissions.record.create({ contentType: typeSlug })}
				LoadingComponent={EditorSkeleton}
			>
				<ContentEditorPageInternal typeSlug={typeSlug} />
			</PermissionRouteAccess>
		);
	}
	return <AuthorizedExistingContentEditorPage typeSlug={typeSlug} id={id} />;
}

function AuthorizedExistingContentEditorPage({
	typeSlug,
	id,
}: {
	typeSlug: string;
	id: string;
}) {
	const { item } = useSuspenseContentItem(typeSlug, id);
	if (!item) return <ContentEditorPageInternal typeSlug={typeSlug} id={id} />;
	return (
		<PermissionRouteAccess
			permission={cmsPermissions.record.update({
				contentType: item.contentType?.slug ?? typeSlug,
				recordId: item.id,
				...(item.authorId ? { authorId: item.authorId } : {}),
			})}
			LoadingComponent={EditorSkeleton}
		>
			<ContentEditorPageInternal typeSlug={typeSlug} id={id} />
		</PermissionRouteAccess>
	);
}

