										{localization?.CMS_BUTTON_CREATE ??
											t("cms.common.create", "Create")}
									</Button>
								</PermissionAccess>
							}
						/>
					)
				) : (
					<ContentTable
						items={items}
						total={total}
						typeSlug={typeSlug}
						basePath={basePath}
						LinkComponent={LinkComponent}
						navigate={navigate}
						onDelete={handleDelete}
						isDeleting={deleteContent.isPending}
						formatDate={formatDate}
						loadMore={loadMore}
						hasMore={hasMore}
						isLoadingMore={isLoadingMore}
						localization={localization}
						classNames={classNames}
						t={t}
					/>
				)}
			</div>
		</PageWrapper>
	);
}

function ContentTable({
	items,
	total,
	typeSlug,
	basePath,
	LinkComponent,
	navigate,
	onDelete,
	isDeleting,
	formatDate,
	loadMore,
	hasMore,
	isLoadingMore,
	localization,
	classNames,
	t,
}: {
	items: SerializedContentItemWithType[];
	total: number;
	typeSlug: string;
	basePath: string;
	LinkComponent: React.ElementType;
	navigate?: (path: string) => void | Promise<void>;
	onDelete: (id: string) => void;
	isDeleting: boolean;
	formatDate: (dateString: string) => string;
	loadMore: () => void;
	hasMore: boolean;
	isLoadingMore: boolean;
	localization: CMSPluginOverrides["localization"];
	classNames: CMSPluginOverrides["classNames"];
	t: TranslateFn;
}) {
	return (
		<div
			className={cn("border rounded-lg", classNames?.table)}
			data-testid="cms-content-table"
		>
			<Table>
				<TableHeader>
					<TableRow>
						<TableHead>
							{localization?.CMS_LIST_COLUMN_SLUG ??
								t("cms.list.columnSlug", "Slug")}
						</TableHead>
						<TableHead>
							{localization?.CMS_LIST_COLUMN_CREATED ??
								t("cms.list.columnCreated", "Created")}
						</TableHead>
						<TableHead>
							{localization?.CMS_LIST_COLUMN_UPDATED ??
								t("cms.list.columnUpdated", "Updated")}
						</TableHead>
						<TableHead className="w-[100px]">
							{localization?.CMS_LIST_COLUMN_ACTIONS ??
								t("cms.list.columnActions", "Actions")}
						</TableHead>
					</TableRow>
				</TableHeader>
				<TableBody>
					{items.map((item) => (
						<TableRow key={item.id} className={classNames?.tableRow}>
							<TableCell className="font-medium">
								<LinkComponent
									href={joinBasePath(basePath, `/cms/${typeSlug}/${item.id}`)}
									className="hover:underline"
								>
									{item.slug}
								</LinkComponent>
							</TableCell>
							<TableCell>{formatDate(item.createdAt)}</TableCell>
							<TableCell>{formatDate(item.updatedAt)}</TableCell>
							<TableCell>
								<div className="flex items-center gap-1">
									<PermissionAccess
										permission={cmsPermissions.record.update({
											contentType: item.contentType?.slug ?? typeSlug,
											recordId: item.id,
											...(item.authorId ? { authorId: item.authorId } : {}),
										})}
									>
										<Button
											variant="ghost"
											size="icon"
											onClick={() =>
												void navigate?.(
													joinBasePath(basePath, `/cms/${typeSlug}/${item.id}`),
												)
											}
										>
											<Pencil className="h-4 w-4" />
										</Button>
									</PermissionAccess>
									<PermissionAccess
										permission={cmsPermissions.record.delete({
											contentType: item.contentType?.slug ?? typeSlug,
											recordId: item.id,
											...(item.authorId ? { authorId: item.authorId } : {}),
										})}
									>
										<Button
											variant="ghost"
											size="icon"
											onClick={() => onDelete(item.id)}
											disabled={isDeleting}
										>
											<Trash2 className="h-4 w-4 text-destructive" />
										</Button>
									</PermissionAccess>
								</div>
							</TableCell>
						</TableRow>
					))}
				</TableBody>
			</Table>
			{/* Load More and pagination info */}
			<div
				className={cn(
					"flex items-center justify-between px-4 py-3 border-t",
					classNames?.pagination,
				)}
				data-testid="cms-content-pagination"
			>
				<p className="text-sm text-muted-foreground">
					{(
						localization?.CMS_LIST_PAGINATION_SHOWING ??
						t("cms.list.paginationShowing", "Showing {from}-{to} of {total}")
					)
						.replace("{from}", "1")
						.replace("{to}", String(items.length))
						.replace("{total}", String(total))}
				</p>
				{hasMore && (
					<Button
						variant="outline"
						size="sm"
						onClick={() => loadMore()}
						disabled={isLoadingMore}
					>
						{isLoadingMore && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
						{localization?.CMS_LIST_PAGINATION_NEXT ??
							t("cms.list.paginationNext", "Next")}
					</Button>
				)}
			</div>
		</div>
	);
}

